mapper.select:
SELECT R.* FROM (
) R
ORDER BY R."sortDate" DESC, R."reportCategory", R."reportId" DESC OFFSET #{offset} ROWS FETCH FIRST #{size} ROWS ONLY

choose.when:
SELECT project_report_id
FROM project_reports
WHERE project_report_id = #{reportId}
	AND project_id = #{projectId}
	FOR UPDATE

choose.otherwise:
SELECT team_report_id
FROM team_reports
WHERE team_report_id = #{reportId}
	AND project_id = #{projectId}
	AND deleted IS NULL
	FOR UPDATE

mapper.select:
SELECT project_id
FROM projects
WHERE project_id = #{projectId}
	AND workspace_id = #{workspaceId}
	AND deleted IS NULL
	FOR UPDATE

mapper.update:
UPDATE project_reports
SET title = #{reportTitle}, content = #{content},
    progress = (
        SELECT NVL(p.progress, 0)
        FROM projects p
        WHERE p.project_id = #{projectId}
          AND p.deleted IS NULL
    ),
    updated = SYSDATE
WHERE project_report_id = #{reportId} AND project_id = #{projectId}

mapper.delete:
DELETE
FROM project_reports
WHERE project_report_id = #{reportId}
	AND project_id = #{projectId}

mapper.select:
SELECT report_file_id AS "fileId", original_name AS "originalName", stored_name AS "storedName",
	path AS "path", file_size AS "fileSize"
FROM report_files


		WHERE project_report_id = #{reportId}


		WHERE team_report_id = #{reportId}


ORDER BY report_file_id

mapper.delete:
DELETE
FROM report_files
WHERE project_report_id = #{reportId}
	AND report_file_id = #{fileId}

mapper.select:
SELECT R.* FROM (
) R JOIN (
) C ON C."reportCategory" = #{currentCategory} AND C."reportId" = #{reportId} WHERE ( R."sortDate" > C."sortDate" OR (R."sortDate" = C."sortDate" AND R."reportCategory" < C."reportCategory") OR (R."sortDate" = C."sortDate" AND R."reportCategory" = C."reportCategory" AND R."reportId" > C."reportId") )
ORDER BY R."sortDate" ASC, R."reportCategory" DESC, R."reportId" ASC FETCH FIRST 1 ROW ONLY

SELECT R.* FROM (
) R JOIN (
) C ON C."reportCategory" = #{currentCategory} AND C."reportId" = #{reportId} WHERE ( R."sortDate" < C."sortDate" OR (R."sortDate" = C."sortDate" AND R."reportCategory" > C."reportCategory") OR (R."sortDate" = C."sortDate" AND R."reportCategory" = C."reportCategory" AND R."reportId" < C."reportId") )
ORDER BY R."sortDate" DESC, R."reportCategory", R."reportId" DESC FETCH FIRST 1 ROW ONLY

SELECT COUNT(*)
FROM project_members pm
WHERE pm.project_member_id = #{reviewerProjectMemberId}
	AND pm.role = 70
	AND pm.status = 0
	AND pm.project_member_id != #{authorProjectMemberId}
